mapper.select:
SELECT CAST(o.order_id AS TEXT) AS orderId, o.account_id AS accountId, CONCAT(u.first_name, ' ', COALESCE(u.last_name, '')) AS holderName, o.ticker AS symbol, o.side AS side, CAST(o.quantity AS BIGINT) AS quantity, o.price AS price, COALESCE(o.order_type, 'LIMIT') AS orderType, CASE WHEN o.status = 'FILLED' THEN o.executed_price ELSE NULL END AS executedPrice, o.status AS status, o.idempotency_key AS idempotencyKey, o.received_at AS createdOn FROM orders o JOIN account a ON a.account_id = o.account_id JOIN auth.users u ON u.user_id = a.user_id
AND o.status = #{status}
AND o.account_id = #{accountId}
ORDER BY o.received_at DESC, o.order_id DESC
LIMIT #{limit}
